#include "FiveSenseFusionModel.h"
#include <algorithm>
#include <cmath>
namespace dnxr { FiveSenseFusionOutput FiveSenseFusionModel::fuse(const FiveSenseNeuralState& s) const { FiveSenseFusionOutput o; auto coh=[](float a,float b){return 1.0f-std::clamp(std::fabs(a-b),0.0f,1.0f);}; o.visualAuditoryCoherence=coh(s.visualState.latencyMs/100.0f,s.auditoryState.latencyMs/100.0f); o.visualVestibularCoherence=coh(s.visualState.currentIntensity,s.vestibularState.currentIntensity); o.hapticProprioceptiveCoherence=coh(s.somatosensoryState.currentIntensity,s.proprioceptiveState.currentIntensity); o.smellTasteCoherence=coh(s.olfactoryState.currentIntensity,s.gustatoryState.currentIntensity); o.bodySceneCoherence=coh(s.realityAnchorState.confidence,s.proprioceptiveState.confidence); o.globalPerceptualCoherence=std::min({o.visualAuditoryCoherence,o.visualVestibularCoherence,o.hapticProprioceptiveCoherence,o.smellTasteCoherence,o.bodySceneCoherence}); if(o.globalPerceptualCoherence<0.65f||s.globalRisk()>0.75f){o.safetyPriorityReduction=true;o.realityAnchorStrength=1.0f;o.reason="unstable_perception_reality_anchor_forced";} return o; } }
